import {readFileSync,readdirSync} from 'node:fs';
import {basename,resolve} from 'node:path';
import {pathToFileURL} from 'node:url';
import {gzipSync} from 'node:zlib';
import {initSync,parse} from 'es-module-lexer';
const assets=process.argv[2]?pathToFileURL(resolve(process.argv[2])+'/'):new URL('../build/client/assets/',import.meta.url),files=readdirSync(assets);
initSync();
const imports=file=>parse(readFileSync(new URL(file,assets),'utf8'))[0].filter(i=>i.n&&(i.n.startsWith('.')||i.n.startsWith('/assets/')));
const graph=(entries,dynamic=false)=>{const seen=new Set();const visit=file=>{if(seen.has(file))return;seen.add(file);for(const i of imports(file))if(dynamic||i.d===-1)visit(basename(i.n));};entries.forEach(visit);return [...seen];};
const kb=entries=>entries.reduce((n,file)=>n+gzipSync(readFileSync(new URL(file,assets))).length/1024,0);
const worker=files.find(f=>/^optionDeltas\.worker-.*\.js$/.test(f));
if(!worker)throw Error('Build the app before measuring.');
const reachable=graph([worker],true),initial=graph([worker]);
const matching=prefixes=>reachable.filter(f=>prefixes.some(prefix=>f.startsWith(prefix+'-')));
const measured=matching(['siteModelRuntime','siteSurfaceEngine']);
const advanced=matching(['yardModelAdvancedRuntime']);
const stepped=matching(['wallTopStepsRuntime','wallStationRuntime','stairTargetsRuntime']);
const landscape=matching(['landscapeTypesRuntime','landscapeModelRuntime','editorOrganizationRuntime']);
const quote=matching(['quoteResolutions']);
const pool=matching(['poolModelRuntime','poolTypesRuntime','poolQuoteRuntime','poolQuoteTypesRuntime','poolDrawingsRuntime','poolDesignExtensionsRuntime']);
const cases={poolFirstJob:graph([worker,...advanced,...pool]),poolSiteLandscapeFirstJob:graph([worker,...advanced,...measured,...stepped,...landscape,...quote,...pool]),bootstrap:[worker],legacyFirstJob:initial,advancedFinishedFirstJob:graph([worker,...advanced]),measuredSiteFirstJob:graph([worker,...advanced,...measured]),steppedWallStairFirstJob:graph([worker,...advanced,...stepped]),fullOptionalFirstJob:graph([worker,...advanced,...measured,...stepped,...landscape,...quote])};
const report=Object.fromEntries(Object.entries(cases).map(([name,list])=>[name,{gzipKB:Number(kb(list).toFixed(3)),chunks:list.length}]));
const manifestFile=files.find(f=>/^manifest-.*\.js$/.test(f)),manifest=JSON.parse(readFileSync(new URL(manifestFile,assets),'utf8').replace(/^window\.__reactRouterManifest=/,'').replace(/;\s*$/,''));
const route=Object.values(manifest.routes).find(r=>/\/DeckDesigner-[^/]+\.js$/.test(r.module));
const shared=new Set([manifest.entry.module,...manifest.entry.imports,manifest.routes.root.module,...(manifest.routes.root.imports??[])]);
const routeFiles=[route.module,...(route.imports??[])].filter(m=>!shared.has(m)).map(file=>basename(file));
const routeCss=(route.css??[]).filter(file=>!(manifest.routes.root.css??[]).includes(file)).map(file=>basename(file));
console.log(JSON.stringify({route:{gzipKB:Number(kb(routeFiles).toFixed(3)),cssGzipKB:Number(kb(routeCss).toFixed(3))},worker,report,optionalEntries:{advanced,measured,stepped,landscape,quote,pool}},null,2));
